fn binary_search_recursive(v: &[i32], elem: i32, c: isize, f: isize) -> isize {
    // If the search interval [c..=f] is empty, the last position
    // whose element is ≤ elem is f (which may be -1).
    if c > f {
        return f;
    }

    // Compute midpoint in a way that avoids overflow.
    let mid = c + (f - c) / 2;
    let mid_usize = mid as usize;

    if v[mid_usize] <= elem {
        // The element at mid is ≤ target, so the answer lies in [mid+1..=f]
        binary_search_recursive(v, elem, mid + 1, f)
    } else {
        // The element at mid is > target, so the answer lies in [c..=mid-1]
        binary_search_recursive(v, elem, c, mid - 1)
    }
}

fn main() {
    // Example usage:
    let v = vec![-5, 0, 0, 3, 7, 7, 10];
    let target = 7;
    // Initial bounds: c = 0, f = v.len() as isize - 1
    let idx = binary_search_recursive(&v, target, 0, v.len() as isize - 1);
    println!("Last position ≤ {}: {}", target, idx); // prints 5

    let target2 = -6;
    let idx2 = binary_search_recursive(&v, target2, 0, v.len() as isize - 1);
    println!("Last position ≤ {}: {}", target2, idx2); // prints -1
}